const nonnegative = z.number().int().min(0).max(1_000_000_000);
const positive = nonnegative.min(1);
const text = z.string().trim().min(1).max(4000);
const ref = z.object({ id }).strict();
const uniqueIds = z.array(id).min(1).max(100).refine(a => new Set(a).size === a.length, 'duplicate IDs');
const taxSchema = z.object({ mode:z.enum(['VAT','EXEMPT','REVERSE_CHARGE']),rateBps:nonnegative.max(10000),display:z.enum(['NET','GROSS']),legalApprovalId:id.optional(),testOnly:z.boolean().default(false) }).strict().refine(t => t.mode === 'VAT' || t.rateBps === 0, 'exempt and reverse charge have zero charged tax');
const contactSchema = z.object({name:text,email:z.string().email().optional(),phone:z.string().min(5).max(40).optional()}).strict().refine(c=>Boolean(c.email||c.phone),'contact channel required');
const leadFacts = z.object({ customerType:z.enum(['B2B','B2C','B2G']).optional(),propertyType:text.optional(),condition:text.optional(),address:text.optional(),area:text.optional(),quantityMilli:positive.optional(),measurementSource:z.enum(['CUSTOMER_STATED','VERIFIED']).optional(),desiredPeriod:text.optional(),recurring:z.boolean().optional(),access:text.optional(),restrictions:text.optional(),locations:z.array(text).max(100).optional(),photoIds:z.array(id).max(30).optional() }).strict();
const serviceSchema = z.object({ name:text,description:text,unit:z.enum(['PERSON_HOUR','M2','UNIT','FIXED']),model:z.enum(['HOURLY','AREA','UNIT','FIXED','MIXED']),active:z.boolean().default(false),included:z.array(text).max(50).default([]),excluded:z.array(text).max(50).default([]),questions:z.array(text).max(30).default([]),requiredSkills:z.array(id).max(30).default([]),requiresVisit:z.boolean().default(false) }).strict();
const ruleSchema = z.object({serviceId:id,rateCents:nonnegative,minimumQuantityMilli:nonnegative.default(0),minimumCents:nonnegative.default(0),included:z.boolean().default(false)}).strict();
const delegationSchema = z.object({minNetCents:nonnegative,maxNetCents:positive,maxDiscountBps:nonnegative.max(10000),legalTemplateId:id,territories:z.array(text).min(1).max(100),approvedBy:id.optional(),approvedAt:timestamp.optional()}).strict().refine(d=>d.maxNetCents>=d.minNetCents);
const priceBookSchema = z.object({ name:text,validFrom:timestamp,validUntil:timestamp.optional(),currency:z.literal('EUR').default('EUR'),tax:taxSchema,rules:z.array(ruleSchema).min(1).max(100).refine(a=>new Set(a.map(r=>r.serviceId)).size===a.length),mode:z.enum(['GUIDED','DELEGATED_STANDARD']).default('GUIDED'),delegation:delegationSchema.optional() }).strict().refine(p=>!p.validUntil||Date.parse(p.validUntil)>Date.parse(p.validFrom));
const quoteInput = z.object({leadId:id,priceBookId:id,lines:z.array(z.object({serviceId:id,quantityMilli:positive}).strict()).min(1).max(100).refine(a=>new Set(a.map(l=>l.serviceId)).size===a.length),expiresAt:timestamp,scope:text,included:z.array(text).max(100).default([]),excluded:z.array(text).max(100).default([]),legalTemplateId:id,pricingModel:z.enum(['FIXED','TIME_MATERIAL']),discountBps:nonnegative.max(10000).default(0),certainty:z.enum(['ESTIMATE','CONTRACT_PRICE']).default('ESTIMATE')}).strict();
const date = (s:string) => Date.parse(s);
const money = (n:number) => { assert(Number.isSafeInteger(n)&&n>=0,'VALIDATION_ERROR'); return n; };
const bps = (n:number,rate:number) => Number((BigInt(money(n))*BigInt(rate)+5000n)/10000n);
const save = (c:CommandContext,e:Entity,data:Data) => c.tx.save(e,data,c.expectedVersion??e.version);
const command = (permission:string,schema:z.ZodTypeAny,handler:(ctx:CommandContext,input:any)=>Promise<any>,highRisk=false)=>({permission,schema,handler,highRisk});
const openLead = (s:string)=>!['CONVERTED','LOST','WITHDRAWN'].includes(s);

async function legalGate(c:CommandContext,subject:string,approvalId?:string,testOnly=false) {
  if(testOnly) {
    const company=await c.tx.get('company',c.actor.companyId);
    assert(['DEMO','TEST'].includes(company.data.operatingMode),'NEEDS_APPROVAL',{subject});
    return;
  }
  assert(approvalId,'NEEDS_APPROVAL',{subject});
  const approval=await c.tx.get('legal_approval',approvalId);
  assert(approval.data.status==='APPROVED'&&approval.data.subject===subject&&approval.data.active!==false&&(!approval.data.expiresAt||date(approval.data.expiresAt)>date(c.now)),'NEEDS_APPROVAL',{subject});
}
const externalSalesActor=(c:CommandContext)=>c.actor.roles.some(r=>['CLIENT','CUSTOMER','EXTERNAL_BAULEITER','GUEST'].includes(r));
const internalSalesManager=(c:CommandContext)=>isManager(c.actor)&&!externalSalesActor(c);
function currentCustomerMembership(c:CommandContext,m:Entity,customerId:string,capability:string){return m.data.active===true&&!m.data.revokedAt&&(!m.data.expiresAt||date(m.data.expiresAt)>date(c.now))&&m.data.userId===c.actor.userId&&m.data.customerId===customerId&&(m.data.permissions??[]).includes(capability);}
async function customerAccess(c:CommandContext,customerId:string,capability='VIEW',siteId?:string) {
  if(internalSalesManager(c)) return;
  const memberships=await c.tx.list('customer_membership');
  assert(memberships.some(m=>currentCustomerMembership(c,m,customerId,capability)&&(!siteId||!(m.data.siteIds??[]).length||m.data.siteIds.includes(siteId))),'NOT_FOUND_SAFE');
}
async function quoteSiteId(c:CommandContext,quote:Entity,lead?:Entity):Promise<string|undefined>{
 if(quote.data.siteId)return quote.data.siteId;
 if(quote.data.orderId){const order=await c.tx.get('order',quote.data.orderId);if(order.data.siteId)return order.data.siteId;}
 const relatedLead=lead??await c.tx.get('lead',quote.data.leadId);
 if(relatedLead.data.siteId)return relatedLead.data.siteId;
 if(relatedLead.data.orderId){const order=await c.tx.get('order',relatedLead.data.orderId);if(order.data.siteId)return order.data.siteId;}
 return undefined;
}
async function salesPhotos(c:CommandContext,photoIds:string[]=[],lead?:Entity){for(const photoId of photoIds){const media=await c.tx.get('media_asset',photoId);assert(media.data.visibility!=='CONFIDENTIAL'&&String(media.data.mimeType).startsWith('image/')&&['RECEIVED','APPROVED_FOR_CLIENT'].includes(media.data.state),'NOT_FOUND_SAFE');assert(media.data.uploadedBy===c.actor.userId||media.data.uploadedBy===lead?.data.ownerUserId||isManager(c.actor),'NOT_FOUND_SAFE');if(media.data.siteId){const site=await c.tx.get('site',media.data.siteId);if(lead?.data.customerId)assert(site.data.customerId===lead.data.customerId,'NOT_FOUND_SAFE');if(!isManager(c.actor))await customerAccess(c,site.data.customerId,'VIEW',site.id);}}}
async function leadAccess(c:CommandContext,e:Entity) {
  if(!externalSalesActor(c)&&(isManager(c.actor)||c.actor.permissions.includes('commerce.manage')))return;
  if(e.data.customerId) return customerAccess(c,e.data.customerId,'VIEW',e.data.siteId);
  assert(e.data.ownerUserId===c.actor.userId,'NOT_FOUND_SAFE');
}
async function addDecision(c:CommandContext,data:Data,key?:string) {
  if(key) {const found=(await c.tx.list('decision')).find(e=>e.data.dedupeKey===key);if(found)return found;}
  const decision=await c.tx.add('decision',{status:'OPEN',ownerId:c.actor.userId,openedAt:c.now,history:[],...data,dedupeKey:key});
  await c.tx.event('decision.opened',{decisionId:decision.id,...data});return decision;
}
async function validBook(c:CommandContext,book:Entity) {
  assert(book.data.status==='ACTIVE'&&date(book.data.validFrom)<=date(c.now)&&(!book.data.validUntil||date(book.data.validUntil)>date(c.now)),'INVALID_STATE',{reason:'PRICE_BOOK_NOT_CURRENT'});
  await legalGate(c,'TAX_PROFILE',book.data.tax.legalApprovalId,book.data.tax.testOnly);
}
async function calculate(c:CommandContext,book:Entity,inputs:{serviceId:string;quantityMilli:number}[],discountBps:number) {
  const lines=[];let subtotalNetCents=0;
  for(const input of inputs) {
    const service=await c.tx.get('service',input.serviceId);assert(service.data.active,'INVALID_STATE',{reason:'SERVICE_INACTIVE'});
    const rule=book.data.rules.find((r:Data)=>r.serviceId===input.serviceId);assert(rule,'NEEDS_APPROVAL',{reason:'UNKNOWN_PRICE'});
    assert(service.data.unit!=='FIXED'||input.quantityMilli===1000,'VALIDATION_ERROR',{reason:'FIXED_QUANTITY_MUST_BE_ONE'});
    const quantityMilli=Math.max(input.quantityMilli,rule.minimumQuantityMilli);
    const netCents=rule.included?0:Math.max(cents(quantityMilli,rule.rateCents),rule.minimumCents);
    subtotalNetCents=money(subtotalNetCents+netCents);
    lines.push({...input,quantityMilli,unit:service.data.unit,serviceName:service.data.name,serviceVersion:service.version,catalogApproved:Boolean(service.data.approvedBy),serviceDescription:service.data.description,serviceIncluded:service.data.included,serviceExcluded:service.data.excluded,requiredSkills:service.data.requiredSkills,rateCents:rule.rateCents,netCents,included:rule.included,source:{priceBookId:book.id,priceBookVersion:book.version},rounding:'HALF_UP_TO_CENT',tax:{...book.data.tax}});
  }
  const discountCents=bps(subtotalNetCents,discountBps),totalNetCents=subtotalNetCents-discountCents,totalTaxCents=bps(totalNetCents,book.data.tax.rateBps);
  return {lines,subtotalNetCents,discountCents,totalNetCents,totalTaxCents,totalGrossCents:money(totalNetCents+totalTaxCents)};
}
async function makeQuote(c:CommandContext,input:z.infer<typeof quoteInput>,previous?:Entity) {
  const lead=await c.tx.get('lead',input.leadId);await leadAccess(c,lead);
  assert(['QUALIFIED','QUOTING'].includes(lead.data.status),'INVALID_STATE',{reason:'LEAD_NOT_QUALIFIED'});
  assert(lead.data.ownership!=='HUMAN_ACTIVE'||c.actor.roles.some(r=>['OWNER','DIRECTOR','OPERATIONS_MANAGER','DISPATCHER'].includes(r)),'NEEDS_APPROVAL',{reason:'HUMAN_HANDOFF_ACTIVE'});
  const book=await c.tx.get('price_book',input.priceBookId);await validBook(c,book);
  assert(date(input.expiresAt)>date(c.now),'VALIDATION_ERROR',{reason:'EXPIRY_IN_PAST'});
  assert(input.lines.every(l=>lead.data.serviceIds.includes(l.serviceId)),'NEEDS_APPROVAL',{reason:'SERVICE_NOT_IN_QUALIFIED_SCOPE'});
  const totals=await calculate(c,book,input.lines,input.discountBps);
  const qualified=lead.data.facts.measurementSource==='VERIFIED'||input.lines.every(l=>totals.lines.find(line=>line.serviceId===l.serviceId)?.unit==='FIXED'&&l.quantityMilli===1000);
  const delegation=book.data.delegation;
  const canonicalScope=totals.lines.map(l=>l.serviceDescription).join('; ');
  const standardScope=input.scope===canonicalScope&&JSON.stringify([...input.included].sort())===JSON.stringify([...new Set(totals.lines.flatMap(l=>l.serviceIncluded))].sort())&&JSON.stringify([...input.excluded].sort())===JSON.stringify([...new Set(totals.lines.flatMap(l=>l.serviceExcluded))].sort());
  const delegated=book.data.mode==='DELEGATED_STANDARD'&&delegation&&delegation.approvedBy&&qualified&&standardScope&&totals.lines.every(l=>l.catalogApproved)&&totals.totalNetCents>=delegation.minNetCents&&totals.totalNetCents<=delegation.maxNetCents&&input.discountBps<=delegation.maxDiscountBps&&input.legalTemplateId===delegation.legalTemplateId&&delegation.territories.includes(lead.data.facts.area??lead.data.facts.address);
  if(delegated)await legalGate(c,'QUOTE_TEMPLATE',input.legalTemplateId,book.data.tax.testOnly);
  const siblings=(await c.tx.list('quote')).filter(q=>q.data.leadId===lead.id);
  const quoteVersion=Math.max(0,...siblings.map(q=>q.data.quoteVersion))+1;
  const quote=await c.tx.add('quote',{...input,...totals,leadId:lead.id,customerId:lead.data.customerId,ownerUserId:lead.data.ownerUserId,quoteVersion,priceBookVersion:book.version,tax:{...book.data.tax},currency:'EUR',status:delegated?'APPROVED_TO_SEND':'DRAFT',approvalMode:delegated?'DELEGATED_STANDARD':'GUIDED',approvedBy:delegated?delegation.approvedBy:undefined,approvedAt:delegated?c.now:undefined,requiresHumanReview:book.data.mode==='DELEGATED_STANDARD'&&!delegated,snapshot:{contact:lead.data.contact,facts:lead.data.facts,customerType:lead.data.facts.customerType,serviceDescriptions:totals.lines.map(l=>({serviceId:l.serviceId,name:l.serviceName,version:l.serviceVersion}))},supersedesId:previous?.id});
  if(previous)await c.tx.save(previous,{...previous.data,status:'SUPERSEDED',supersededBy:quote.id},previous.version);
  await c.tx.save(lead,{...lead.data,status:'QUOTING',currentQuoteId:quote.id},lead.version);
  if(quote.data.requiresHumanReview)await addDecision(c,{reason:'NON_STANDARD_QUOTE',leadId:lead.id,quoteId:quote.id,amountCents:totals.totalNetCents,actions:['APPROVE','RETURN','DELEGATE']},`quote-review:${quote.id}`);
  await c.tx.event('quote.created',{quoteId:quote.id,quoteVersion,status:quote.data.status});return quote;
}
async function slotConflict(c:CommandContext,employeeIds:string[],startAt:string,endAt:string,excludeId?:string,orderId?:string) {
  assert(date(startAt)<date(endAt)&&date(startAt)>=date(c.now),'VALIDATION_ERROR',{reason:'INVALID_SLOT'});
  const assignments=await c.tx.list('crew_assignment'),reservations=await c.tx.list('schedule_reservation');
  for(const employeeId of employeeIds) {
    const employee=await c.tx.get('employee',employeeId);
    assert(employee.data.active!==false,'INVALID_STATE',{reason:'EMPLOYEE_INACTIVE',employeeId});
    const company=await c.tx.get('company',c.actor.companyId);
    if(!['DEMO','TEST'].includes(company.data.operatingMode))assert(employee.data.availabilityReviewedAt&&employee.data.availabilityValidUntil&&date(employee.data.availabilityValidUntil)>date(c.now),'NEEDS_APPROVAL',{reason:'CURRENT_AVAILABILITY_REQUIRED',employeeId});
    const windows=employee.data.availabilityWindows??[];if(windows.length)assert(windows.some((w:Data)=>date(w.startAt)<=date(startAt)&&date(w.endAt)>=date(endAt)),'INVALID_STATE',{reason:'OUTSIDE_AVAILABILITY',employeeId});
    const bufferMs=(employee.data.travelBufferMinutes??0)*60000;
    const unavailable=(employee.data.absences??[]).some((a:Data)=>date(a.startAt)<date(endAt)&&date(a.endAt)>date(startAt));
    assert(!unavailable,'INVALID_STATE',{reason:'EMPLOYEE_ABSENT',employeeId});
    const busy=[...assignments.filter(a=>a.data.status!=='CANCELLED'&&a.data.status!=='COMPLETED'),...reservations.filter(r=>r.data.status==='ACTIVE'&&date(r.data.expiresAt)>date(c.now))].find(a=>a.id!==excludeId&&a.data.orderId!==orderId&&a.data.employeeIds.includes(employeeId)&&date(a.data.startAt)-bufferMs<date(endAt)&&date(a.data.endAt)+bufferMs>date(startAt));
    assert(!busy,'VERSION_CONFLICT',{reason:'SCHEDULE_CONFLICT',employeeId,conflictId:busy?.id});
  }
}
async function requireSkills(c:CommandContext,order:Entity,employeeIds:string[]) {
  const quote=await c.tx.get('quote',order.data.quoteId);
  const required=new Set<string>(quote.data.lines.flatMap((l:Data)=>l.requiredSkills??[]));
  const employees=await Promise.all(employeeIds.map(employeeId=>c.tx.get('employee',employeeId)));
  for(const skill of required)assert(employees.some(e=>(e.data.skills??[]).some((s:string|Data)=>typeof s==='object'&&s.id===skill&&s.verified&&(!s.expiresAt||date(s.expiresAt)>date(c.now)))),'NEEDS_APPROVAL',{reason:'MISSING_VERIFIED_SKILL',skill});
}
async function materialsReady(c:CommandContext,orderId:string) {
 const requirements=(await c.tx.list('material_requirement')).filter(r=>r.data.orderId===orderId);
 for(const requirement of requirements){if(!requirement.data.requestId)return false;const request=await c.tx.get('material_request',requirement.data.requestId);if(request.data.materialId!==requirement.data.materialId||request.data.siteId!==requirement.data.siteId||request.data.approvedBase<requirement.data.quantityBase)return false;if(request.data.receivedBase>=requirement.data.quantityBase)continue;const reservations=(await c.tx.list('stock_reservation')).filter(r=>r.data.requestId===request.id&&r.data.state==='ACTIVE'&&date(r.data.expiresAt)>date(c.now));const held=reservations.reduce((n,r)=>n+r.data.quantityBase-r.data.issuedBase,0);if(held+request.data.receivedBase<requirement.data.quantityBase)return false;const {stockBalance}=await import('./resources.js');for(const reservation of reservations){const balance=await stockBalance(c,reservation.data.materialId,reservation.data.locationId,reservation.data.batchId);if(balance.usableBase<reservation.data.quantityBase-reservation.data.issuedBase)return false;}}
 return true;
}
async function issueSchedule(c:CommandContext,order:Entity,assignment:Entity) {
  if(assignment.data.requireEmployeeAck&&!assignment.data.employeeIds.every((employeeId:string)=>assignment.data.acknowledgedIds.includes(employeeId)))return;
  const fresh=await c.tx.get('order',order.id);
  if(!await materialsReady(c,order.id)){await addDecision(c,{reason:'DISPATCH_MATERIALS_NOT_READY',orderId:order.id,siteId:assignment.data.siteId,actions:['CHANGE','RETURN','DELEGATE'],summaryDE:'Materialbedarf ist noch nicht gedeckt; Kundentermin bleibt unbestätigt.'},`dispatch-materials:${order.id}:${assignment.data.scheduleVersion}`);return;}
  if(fresh.data.schedulePublishedVersion===assignment.data.scheduleVersion)return;
  await c.tx.save(fresh,{...fresh.data,status:'SCHEDULED',schedulePublishedVersion:assignment.data.scheduleVersion,confirmedStartAt:assignment.data.startAt,confirmedEndAt:assignment.data.endAt},fresh.version);
  await c.tx.event('dispatch.schedule_confirmed',{orderId:order.id,assignmentId:assignment.id,customerId:order.data.customerId,siteId:assignment.data.siteId,startAt:assignment.data.startAt,endAt:assignment.data.endAt,scheduleVersion:assignment.data.scheduleVersion,employeeIds:assignment.data.employeeIds});
}

